fun isRoomDatabaseBackupFile(name: String): Boolean {
    return (name.startsWith(AUTO_BACKUP_FILE_PREFIX) || name.startsWith(MANUAL_BACKUP_FILE_PREFIX)) &&
        name.endsWith(".zip")
}

private suspend fun deleteSelectedChatHistories(
    context: Context,
    selectedChatIds: List<String>
): DeleteSelectedChatsResult =
    withContext(Dispatchers.IO) {
        val chatHistoryManager = ChatHistoryManager.getInstance(context)
        var deletedCount = 0
        var skippedLockedCount = 0

selectedChatIds.forEach { chatId ->
    val deleted = chatHistoryManager.deleteChatHistory(chatId)
    if (deleted) {
        deletedCount++
    } else {
        skippedLockedCount++
    }
}

